select '1. folders can nest' as check, case when exists ( select 1 from information_schema.columns where table_schema = 'public' and table_name = 'note_folders' and column_name = 'parent_id' ) then 'OK' else 'PROBLEM - 0035 did not run' end as result; select '2. names unique per place' as check, case when exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'note_folders_owner_name') then 'PROBLEM - the old index is still there' when exists (select 1 from pg_indexes where schemaname = 'public' and indexname = 'note_folders_owner_parent_name') then 'OK' else 'PROBLEM - neither index exists' end as result; select '3. depth limit enforced' as check, case when exists ( select 1 from pg_trigger where tgrelid = 'public.note_folders'::regclass and tgname = 'note_folders_depth' ) then 'OK' else 'PROBLEM - the trigger is missing' end as result; select '4. colour labels' as check, case when ( select count(*) from information_schema.columns where table_schema = 'public' and column_name = 'color' and table_name in ('note_folders', 'notes') ) = 2 then 'OK' else 'PROBLEM - missing from one or both tables' end as result; select '5. body_format defaults to plain' as check, case when exists ( select 1 from information_schema.columns where table_schema = 'public' and table_name = 'notes' and column_name = 'body_format' and column_default like '%plain%' ) then 'OK' else 'PROBLEM - missing or wrong default' end as result; select '6. existing notes untouched' as check, case when not exists ( select 1 from information_schema.columns where table_schema = 'public' and table_name = 'notes' and column_name = 'body_format' ) then 'PROBLEM - 0035 did not run' when ( select count(*) from public.notes n where to_jsonb(n) ->> 'body_format' = 'html' and n.body not like '%<%' ) = 0 then 'OK' else 'PROBLEM - some notes were marked as markup unexpectedly' end as result; select '7. still owner-only' as check, case when count(*) = 3 then 'OK' else 'PROBLEM - expected 3 policies across the three tables, found ' || count(*) end as result from pg_policies where schemaname = 'public' and tablename in ('note_folders', 'notes', 'note_checklist_items'); select '8. RLS on' as check, case when count(*) = 3 then 'OK' else 'PROBLEM - only ' || count(*) || ' of 3 tables have it' end as result from pg_tables where schemaname = 'public' and tablename in ('note_folders', 'notes', 'note_checklist_items') and rowsecurity; select coalesce(parent.name, '(top level)') as inside, f.name as folder, coalesce(to_jsonb(f) ->> 'color', '-') as label, (select count(*) from public.notes n where n.folder_id = f.id) as notes from public.note_folders f left join public.note_folders parent on parent.id = (to_jsonb(f) ->> 'parent_id')::uuid order by coalesce(parent.name, ''), f.name;
